export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = inputs.gravity;
  const T = u / g, H = u * u / (2 * g);
  const t = Math.max(0, Math.min(time, 2 * T));
  const yt = u * t - g * t * t / 2;
  const vt = u - g * t;
  const rel = t >= T;
  const tau = Math.max(0, t - T);
  const yd = rel ? H - g * tau * tau / 2 : H;
  const vd = rel ? -g * tau : 0;
  const ad = rel ? -g : 0;
  const x0 = 20, pw = 290, py = 40, ph = 360;
  const bot = py + ph - 30, top = py + 50;
  const Y = (h) => bot - (h / 2.2) * (bot - top);
  const cx1 = x0 + 145, cx2 = x0 + 300 + 145;
  const vs = 12, as = 5;
  const st1 = t < 1e-9 ? 'At launch' : (t < T - 1e-9 ? 'Rising' : (Math.abs(t - T) < 1e-9 ? 'At the top' : (t < 2 * T - 1e-9 ? 'Falling' : 'At launch height')));
  const st2 = !rel ? (t < T ? 'Held in place' : 'Held in place') : (tau < 0.05 ? 'Just released' : (t < 2 * T - 1e-9 ? 'Falling together' : 'At launch height'));
  const o = [];
  o.push(...sdk.panel({ id: 'lane.toss', x: x0, y: py, w: pw, h: ph, title: 'Toss', state: st1, role: 'input' }));
  o.push(...sdk.panel({ id: 'lane.drop', x: x0 + 300, y: py, w: pw, h: ph, title: 'Drop', state: st2, role: 'output' }));
  o.push(sdk.line('mark.toss', x0 + 30, Y(0) + 15, x0 + 260, Y(0) + 15, { role: 'neutral' }));
  o.push(sdk.line('mark.drop', x0 + 330, Y(0) + 15, x0 + 560, Y(0) + 15, { role: 'neutral' }));
  o.push(sdk.circle('ghost.drop', cx2, Y(H), 24, { opacity: 0.25, role: 'output' }));
  o.push(...sdk.gate('gate', cx2, Y(H) + 20, { open: rel, label: 'Gate' }));
  o.push(sdk.circle('ball.toss', cx1, Y(yt), 26, { role: 'input' }));
  o.push(sdk.circle('ball.drop', cx2, Y(yd), 26, { role: 'output' }));
  o.push(...sdk.vector('vec.v.toss', { x: cx1 - 30, y: Y(yt) }, { value: vt, direction: 'up' }, { scale: vs, label: 'v', role: 'observed' }));
  o.push(...sdk.vector('vec.v.drop', { x: cx2 - 30, y: Y(yd) }, { value: vd, direction: 'up' }, { scale: vs, label: 'v', role: 'observed' }));
  o.push(...sdk.vector('vec.a.toss', { x: cx1 + 30, y: Y(yt) }, { value: -g, direction: 'up' }, { scale: as, label: 'a', role: 'warning' }));
  if (rel) o.push(...sdk.vector('vec.a.drop', { x: cx2 + 30, y: Y(yd) }, { value: ad, direction: 'up' }, { scale: as, label: 'a', role: 'warning' }));
  o.push(...sdk.callout(cx1 + 50, Y(yt) - 40, ['v ' + sdk.format(vt, 2) + ' m/s', 'a ' + sdk.format(-g, 1) + ' m/s²'], { id: 'callout.toss' }));
  o.push(...sdk.callout(cx2 + 50, Y(yd) - 40, ['v ' + sdk.format(vd, 2) + ' m/s', 'a ' + sdk.format(ad, 1) + ' m/s²'], { id: 'callout.drop' }));
  return {
    frame: { width: 640, height: 420, objects: o, readouts: [
      { id: 'tossedVelocity', value: vt }, { id: 'tossedAcceleration', value: -g },
      { id: 'dropVelocity', value: vd }, { id: 'dropAcceleration', value: ad }] },
    quantities: { launchSpeed: u, gravity: g, apexTime: T, apexHeight: H, tossedVelocity: vt, tossedAcceleration: -g, tossedHeight: yt, dropVelocity: vd, dropAcceleration: ad, dropHeight: yd }
  };
}
